const badge=(text,cls='')=>`<span class="badge ${cls}${cls==='usage'?(/collection|display/i.test(text)?' collecting':/home/i.test(text)?' home-use':''):''}">${esc(text)}</span>`;
const date=slotforgeDomain.displayDate;
