const usageDefaults=['Collection / Display','Home racing','Club racing','Competition','Testing / Development'];
let db,net,remote=null,source='local',page='Overview',carId=null,section='Overview',selected=new Set(),query='',usage=[],matchAll=false,mode='gallery',sort=CarSort.load().sort,sortDirection=CarSort.load().sortDirection,archived=false,partId=null,partQuery='',reviewId=null,reviewCarId=null,version='',dataPath='',toastTimer;
const current=()=>source==='remote'&&remote?remote:db;
const local=()=>source==='local';
function acceptSnapshot(next){if(db&&db.id===next.id&&db.revision>next.revision)return;db=next;}
function switchCollection(next){workshopJob=null;recentWorkLimit=3;source=next;carId=null;section='Overview';selected.clear();usage=[];query='';archived=false;matchAll=false;}
const car=()=>current().cars.find(c=>c.id===carId);
// Retry storage holds request hashes and IDs only, never entered values.
const saveRetries=SaveRetry.create({storage:{get length(){return localStorage.length;},key:i=>localStorage.key(i),getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)},crypto});
async function api(method,...args){
 const baseline=db,baselinePath=dataPath,epoch=baseline?._view?.token?.epoch;
 const known=baseline?{databaseId:baseline.id,revision:baseline.revision,dataPath:baselinePath,queryView:baseline._view&&!baseline._view.compatibility?(baseline._view.editor?baseline._view.request:desiredView()):undefined}:null;
 const dispatch=async(values,commandId)=>{
  if(method==='mutate'&&baseline)values[2]={...known,...(commandId?{commandId,epoch}:{})};
  if(method==='file'&&baseline?._view)values[2]={queryView:known.queryView};
  const r=await window.slotforge[method](...values);
  if(r?.error)throw Object.assign(new Error(r.error),{code:r.code,definiteRejection:r.definiteRejection===true});
  if(r?.ok!==true)throw Error('Save acknowledgement was lost. Retry the same operation.');
  if(r.value?.dataPatch){const p=r.value.dataPatch;if(!baseline||baseline.id!==p.databaseId||baseline.revision!==p.revision||baselinePath!==p.dataPath)throw Error('The collection changed while refreshing. Reopen the collection.');r.value.data=slotforgeSnapshot.apply(baseline,p.changes);delete r.value.dataPatch;}
  return r.value;
 };
 if(method==='mutate'&&baseline)return saveRetries.run([baselinePath,baseline.id,epoch||'',args[0],args[1]],(value,id)=>dispatch([value[3],value[4]],id));
 return dispatch(args);
}
function toast(message,error=false){clearTimeout(toastTimer);const t=$('#toast');t.textContent=message;t.className=error?'error':'';t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,error?10000:4000);}
async function change(action,p={}){if(!local())throw new Error('Switch to your local database to make changes.');const editor=db._view?.editor,r=await api('mutate',action,p);acceptSnapshot(r.data);if(editor&&db._view)db._view.editor=true;if(r.collection)collectionMeta=r.collection;if(r.club)clubState=r.club;clubQueued(r);return r.result;}
function placeholder(label='Add your own photograph'){return `<div class="placeholder">${icon('car')}<span>${esc(label)}</span></div>`;}
function thumbnailSource(value){return value?.startsWith('paddock-media://')?value+'?thumbnail=1':value;}
function photo(c,thumbnail=false){return c.picture?`<img src="${esc(thumbnail?thumbnailSource(c.picture):c.picture)}" alt="${esc(c.name)}" data-focus-car="${esc(c.id)}" data-focus-photo="main" decoding="async" ${thumbnail?'loading="lazy"':''}>`:placeholder();}
function heading(title,subtitle='',actions=''){return uiHeading(title,subtitle,actions);}
function empty(title,description,action=''){return `<div class="empty"><div class="empty-symbol">${icon('car')}</div><h2>${esc(title)}</h2><p>${esc(description)}</p>${action}</div>`;}
function dl(pairs){return `<dl class="details">${pairs.map(([a,b])=>`<div><dt>${esc(a)}</dt><dd>${esc(b||'—')}</dd></div>`).join('')}</dl>`;}
function timeline(events){return events.length?events.map(e=>`<div class="timeline-item"><span class="timeline-dot"></span><div><time>${date(e.performedDate||e.date)} · ${esc(e.type)}</time><div>${esc(e.title)}</div>${e.notes?`<p>${esc(e.notes)}</p>`:''}${e.nextDue?`<p>Next due: ${date(e.nextDue)}</p>`:''}</div></div>`).join(''):'<p class="muted">Nothing recorded yet.</p>';}
function panel(title,body){return uiPanel(title,body);}
function render(){
  if(queryGate())return;
  const reviewDraft=captureReviewDraft();
  prepareShowroom();
  applyTheme();
  $('#header').innerHTML=`<div class="brand"><span class="brand-mark" aria-hidden="true"><span class="paddock-brand-symbol"></span></span><div><span class="brand-wordmark" role="img" aria-label="SlotForge"><span class="brand-wordmark-size" aria-hidden="true">SlotForge</span><img class="brand-wordmark-light" src="../assets/slotforge-footer-light.png" alt="" width="664" height="124"><img class="brand-wordmark-dark" src="../assets/slotforge-footer-dark.png" alt="" width="664" height="124"></span> Paddock<small>Collection & workshop</small></div></div><nav class="main-nav" aria-label="Main navigation">${navs.map(n=>`<button class="nav-btn ${page===n?'active':''}" data-action="nav" data-id="${esc(n)}" aria-current="${page===n?'page':'false'}">${icon(uiPageIcons[n])}${esc(n)}</button>`).join('')}</nav>${reviewButton()}`;
  $('#database-bar').innerHTML=`<span class="muted">Database</span><select id="database-select" aria-label="Current database"><option value="local">${esc(db.settings.name)}</option>${remote?`<option value="remote" ${source==='remote'?'selected':''}>${esc(remote.settings.name)} · Shared</option>`:''}</select><span class="db-state">${icon('database')} ${local()?(clubState?.active?'Dealership collection copy':clubState?.role==='coordinator'?'Dealership Mode':'Local database'):net.remote?.permissions?.submit?'Shared collection · Submit for review':'Shared collection · Browse only'}</span><span class="spacer"></span><span class="db-state"><span class="dot ${local()?clubState?.active&&clubState.state!=='connected'?'offline':'':net.remote?.state!=='connected'?'offline':''}"></span>${local()?(clubState?.active?(clubState.state==='connected'?'Dealership connected':clubState.state==='outdated'?'Collection copy out of date':'Dealership offline · saved copy'):'Saved on this computer'):net.remote?.state==='connected'?'Connected':'Saved view · offline'}</span>${net.sharing?badge(net.hostingMode==='dealership'?'Dealership online':'Sharing enabled','good'):''}`;
  const views={'Overview':renderOverview,'Showroom':renderShowroom,'Cars':()=>carId&&car()?renderProfile():renderCars(),'Parts':renderParts,'Build from Scratch':()=>local()?renderBuild(''):'<div class="empty">Choose a local collection to build a car from its inventory.</div>','Workshop':renderWorkshop,'Library':renderLibrary,'Connections':renderConnections,'Import & Export':renderExchange,'Settings':renderSettings,'Review':renderReviewHub};
  $('#main').dataset.page=page;
  $('#main').innerHTML=clubBanner()+'<div id="remote-notice">'+remoteNotice()+'</div>'+views[page]()+(local()&&page==='Review'?viewPager(db._view?.list):'');paintCustomTile();applyPhotoFocus();restoreReviewDraft(reviewDraft);releaseInactiveHistory();
}
function renderOverview(){return timingCollectionNotice()+renderOverviewDesign();}
function filteredCars(){if(local()&&db._view?.list)return db.cars;return current().cars.filter(c=>!!c.archived===archived&&(!query||[c.name,c.number,c.maker,c.model,c.reference,c.location,...(c.tags||[]),...Object.values(c.technical||{})].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!usage.length||(matchAll?usage.every(u=>(c.usage||[]).includes(u)):usage.some(u=>(c.usage||[]).includes(u))))).sort((a,b)=>CarSort.compare(a,b,sort,sortDirection));}
function renderCars(){const allUsage=[...new Set([...usageDefaults,...(local()&&db._view?.usage?db._view.usage:current().cars.flatMap(c=>c.usage||[]))])];return heading('Cars',`${local()&&db._view?.activeCars!==undefined?db._view.activeCars:current().cars.filter(c=>!c.archived).length} cars in your collection`,local()?btn(icon('plus')+' Add car','add-car','primary'):'')+`<div class="toolbar"><label class="search">${icon('search')}<input id="car-search" value="${esc(query)}" placeholder="Search cars, parts or tags…" aria-label="Search cars"></label><select id="saved-view" aria-label="Saved view"><option value="">Saved views</option>${current().views.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select><select id="sort" aria-label="Sort cars">${Object.entries(CarSort.fields).map(([v,label])=>`<option ${sort===v?'selected':''} value="${v}">${label}</option>`).join('')}</select><select id="sort-direction" aria-label="Sort direction"><option value="asc" ${sortDirection==='asc'?'selected':''}>${['created','updated'].includes(sort)?'Oldest first':'Ascending'}</option><option value="desc" ${sortDirection==='desc'?'selected':''}>${['created','updated'].includes(sort)?'Newest first':'Descending'}</option></select><div class="segment">${btn(icon('grid')+' Gallery','mode',mode==='gallery'?'on':'','gallery')}${btn(icon('list')+' Table','mode',mode==='table'?'on':'','table')}</div>${local()?btn((query||usage.length||archived?'Select all results':'Select all')+' ('+(db._view?.list?.total??filteredCars().length)+')','select-filtered')+btn('Columns…','configure-columns')+btn('Save view','save-view')+btn('Print / PDF…','reports')+btn('Compare cars…','car-compare')+btn('Compare pace…','compare-pace'):''}</div><div class="filters"><span class="muted tiny">Usage</span>${allUsage.map(u=>`<button class="chip ${usage.includes(u)?'on':''}" aria-pressed="${usage.includes(u)}" data-action="usage" data-id="${esc(u)}">${esc(u)}</button>`).join('')}<select id="match" aria-label="Usage match"><option value="any">Match any</option><option value="all" ${matchAll?'selected':''}>Match all</option></select><label class="check-row tiny"><input id="archived" type="checkbox" ${archived?'checked':''}>Archived / rebuilt</label></div><div id="cars-results">${renderCarResults()}</div>${local()?viewPager(db._view?.list):''}`;}
function renderCarResults(){const list=filteredCars();let bar=selected.size?`<div class="selection-bar"><strong>${selected.size} selected</strong>${local()?btn('Edit selected…','bulk-edit','small primary')+btn(icon('download')+' Export','export-selected','small')+(canSubmit()?btn(icon('share')+' Send to club','send-selected','small'):''):''}${btn('Clear selection','clear-selection','small ghost')}</div>`:'';
  if(!list.length)return bar+empty((db._view?.activeCars??current().cars.length)?'No cars match these filters':'Your collection starts here',(db._view?.activeCars??current().cars.length)?'Try another search or remove a usage filter.':'Add your first car. You only need a name; photos, parts and specifications can come later.',local()?btn(icon('plus')+' Add car','add-car','primary'):'');
  const check=c=>`<input type="checkbox" aria-label="Select ${esc(c.name)}" data-select-car="${c.id}" ${selected.has(c.id)?'checked':''}>`;
  if(mode==='table')return bar+renderCollectionTable(list,check);
  return bar+`<div class="car-grid">${list.map(c=>`<article class="car-card"><label class="car-check">${check(c)}</label><button class="card-photo" data-action="open-car" data-id="${c.id}" aria-label="Open ${esc(c.name)}">${photo(c,true)}</button><div class="card-body"><button class="car-title" data-action="open-car" data-id="${c.id}">${esc(c.name)}</button><div class="card-sub">${esc([c.number,c.maker,c.scale].filter(Boolean).join(' · ')||'Details to add')}</div><div class="row">${(c.usage||[]).slice(0,3).map(u=>badge(u,'usage')).join(' ')}</div><div class="card-foot">${icon('pin')}${esc(c.location||'No location set')}<span class="spacer"></span>${c.availability&&c.availability!=='Available'?badge(c.availability):''}</div></div></article>`).join('')}</div>`;}
const sections=['Overview','Identity & ownership','Technical & parts','Real Car History','Setups','Maintenance','Performance','Photos & documents','History'];
function renderProfile(){const c=car();return `<div class="row">${btn(icon('arrow')+' Cars','back-cars','ghost small')}</div>`+heading(c.name,[c.number,c.maker,c.scale].filter(Boolean).join(' · '),local()?btn('Compare','car-compare','',c.id)+btn('Edit details','edit-car','',c.id)+btn('Add setup','save-setup','',c.id)+btn(icon('tool')+' Record work','add-work','primary',c.id)+btn('More','car-more','',c.id):badge('Shared · Read only'))+(c.rebuild?.to?`<div class="note info rebuild-history-notice"><strong>Rebuilt · historical record</strong><span> New work and races belong to ${esc(c.rebuild.to.name)}.</span>${btn('Continue with rebuilt car '+icon('next'),'rebuild-open','small',c.rebuild.to.id)}</div>`:'')+`<div class="profile-layout"><aside class="rail" aria-label="Car sections"><div class="row">${(c.usage||[]).map(u=>badge(u,'usage')).join('')}</div><hr>${sections.map(s=>`<button class="${section===s?'active':''}" data-action="section" data-id="${s}" aria-current="${section===s?'page':'false'}">${icon(uiSectionIcons[s])}${s}</button>`).join('')}</aside><div class="profile-section-stack">${profileContent(c)}${local()?viewPager(db._view?.history):''}</div></div>`;}
const techGroups={
  'Motor & transmission':[['motor','Motor'],['motorLayout','Motor layout'],['pod','Motor pod'],['podSettings','Pod settings'],['ratedRpm','Rated no-load RPM'],['ratedVoltage','Rated at (V)'],['motorType','Motor type'],['motorTorque','Motor torque (gf·cm)'],['torqueType','Torque rating type'],['torqueVoltage','Torque rated at (V)'],['measuredRpm','Measured RPM'],['measuredVoltage','Measured at (V)'],['measuredDate','Measurement date'],['pinionPart','Pinion component'],['pinion','Pinion teeth'],['gearPart','Driven gear component'],['gear','Driven gear teeth'],['gearType','Gear type / pitch']],
  'Body & chassis':[['body','Body'],['bodyMaterial','Body material'],['bodySettings','Body screw settings'],['chassis','Chassis'],['wheelbase','Wheelbase (mm)'],['weight','Total weight (g)'],['clearance','Ground clearance (mm)']],
  'Wheels tyres & axles':[['frontAxle','Front axle'],['rearAxle','Rear axle'],['frontBearings','Front bearings'],['rearBearings','Rear bearings'],['frontWheels','Front wheels'],['rearWheels','Rear wheels'],['frontTyres','Front tyres'],['rearTyres','Rear tyres'],['frontDiameter','Front tyre diameter (mm)'],['rearDiameter','Rear tyre diameter (mm)'],['frontWidth','Front track width (mm)'],['rearWidth','Rear track width (mm)'],['frontAxlePlay','Front axle play'],['rearAxlePlay','Rear axle play']],
  'Guide electrical & fittings':[['guide','Guide'],['braids','Braids'],['wiring','Wiring'],['lights','Lighting'],['digitalSystem','Digital system'],['chip','Decoder'],['magnets','Magnets'],['ballast','Ballast / placement'],['suspension','Suspension'],['fasteners','Fasteners'],['technicalNotes','Technical notes']]
};
const techLabels=Object.fromEntries(Object.values(techGroups).flat());
function profileContent(c){const d=current(),events=d.events.filter(e=>e.carId===c.id),setups=d.setups.filter(s=>s.carId===c.id);
  if(section==='Overview')return renderCarOverviewDesign(c);
  if(section==='Real Car History')return renderRealHistory(c);
  if(section==='Identity & ownership')return `<div class="two-col">${panel('Identity',dl([['Manufacturer',c.maker],['Reference',c.reference],['Marque',c.marque],['Model',c.model],['Scale',c.scale],['Livery',c.livery],['Race number',c.raceNumber],['Team',c.team],['Edition',c.edition],['Serial',c.serial],['Build origin',c.origin]]))}${panel('Collection & ownership',dl([['Owner',c.owner],['Ownership',c.ownership],['Condition',c.condition],['Packaging',c.packaging],['Location',c.location],['Acquired',c.acquired],['Seller',c.seller],['Purchase price',[c.price,c.currency].filter(Boolean).join(' ')],['Borrower',c.loanTo],['Return due',c.returnDate]]))}</div>${panel('Notes',`<p class="prewrap">${esc(c.description||'No description yet.')}</p>${local()&&c.privateNotes?`<h3>${icon('lock')} Private notes</h3><p class="prewrap">${esc(c.privateNotes)}</p>`:''}${d.customFields.length?dl(d.customFields.map(f=>[f.label,c.custom?.[f.id]])):''}`)}`;
  if(section==='Technical & parts'){const installed=d.installations.filter(i=>i.carId===c.id&&!i.removed);return `<div class="actions">${local()?btn('Edit specifications','edit-car','',c.id)+btn('Install part','install-part','primary',c.id):''}</div><div class="two-col mt">${Object.entries(techGroups).map(([title,fields])=>panel(title,dl([...fields.filter(([k])=>c.technical?.[k]).map(([k,label])=>[label,c.technical[k]]),...(title==='Motor & transmission'?ratioRows(c.technical):[])])||'')).join('')}</div>${PerformanceModel.keys.some(k=>c.technical?.[k])?`<div class="mt">${panel('Theoretical performance',performanceStats(c.technical)+'<p class="tiny muted">Ideal calculations before losses and tyre slip. Stall torque is not available at no-load speed. Peak power uses a linear brushed DC model at matching test voltages and is not a continuous rating.</p>')}</div>`:''}<div class="mt">${panel('Installed inventory',installed.length?installed.map(i=>`<div class="list-row"><div><strong>${esc(d.parts.find(p=>p.id===i.partId)?.name)}</strong><div class="tiny muted">${i.quantity} piece(s) · ${esc(i.position)}</div></div>${local()?(i.assemblyId?btn('Remove assembly…','remove-assembly','small',i.assemblyId):btn('Remove','remove-part','small',i.id)):''}</div>`).join(''):'<p class="muted">No tracked inventory installed. You can still describe all parts in the specifications.</p>')}</div><div class="stack mt">${local()?slotcarResearchTools(c):''}${panel('Factory reference',Object.keys(c.factory||{}).length?dl([...Object.entries(c.factory).filter(([,v])=>v).map(([k,v])=>[techLabels[k]||k,v]),...ratioRows(c.factory)]):'<p class="muted">No factory reference recorded.</p>')}</div>`;}
  if(section==='Setups')return `<div class="page-head"><div><h2>Saved configurations</h2><p class="muted">Snapshots preserve the specifications and tracked components used at that time.</p></div>${local()?btn('Add setup','save-setup','primary',c.id):''}</div>${setups.length?`<div class="setup-grid">${setups.map(s=>panel(s.name,`<div class="tiny muted">${date(s.date)}${s.track?' · '+esc(s.track):''}</div><p class="prewrap mt">${esc(s.notes)}</p>${dl([['Motor',s.technical.motor],...ratioRows(s.technical),['Rear tyres',s.technical.rearTyres],['Weight',s.technical.weight]])}<div class="actions mt">${btn('Compare setups…','compare-setup','',s.id)}${local()?btn('Apply setup…','apply-setup','primary',s.id)+btn('Work in stages…','start-job','',s.id):''}</div>`)).join('')}</div>`:empty('Save your first setup','Capture the current configuration before making changes.',local()?btn('Add setup','save-setup','primary',c.id):'')}`;
  if(section==='Maintenance')return panel('Service & modification journal',`<div class="actions">${local()?btn('Record work','add-work','primary',c.id):''}</div>${timeline(events.filter(e=>['maintenance','modification','installation','removal'].includes(e.type)))}`);
  if(section==='History')return panel('Car history',timeline(events));
  if(section==='Performance'){const tests=d.tests.filter(t=>t.carId===c.id);return `${local()?`<div class="actions">${btn('Compare pace…','compare-pace','',c.id)}</div>`+renderTimingResults(c)+renderLaneRecords(c):''}<hr class="mt"><div class="page-head"><div><h2>Manual test records</h2><p class="muted">Record your own tests independently of imported Timing sessions.</p></div>${local()?btn('Record test','add-test','primary',c.id):''}</div>${tests.length?tests.map(t=>panel(t.track||'Manual test',`<div class="tiny muted">${date(t.date)} · ${esc(t.setupId?'Saved historical snapshot: '+(setups.find(s=>s.id===t.setupId)?.name||'Setup'):'Actual current configuration')}${t.jobId?' · During workshop job':''}</div>${dl([['Recorded motor',t.technical.motor],...ratioRows(t.technical),['Recorded rear tyres',t.technical.rearTyres],['Recorded weight',t.technical.weight]])}<p class="tiny muted">${t.installations?t.installations.length+' tracked component record(s) captured':'Earlier record: no inventory snapshot'}</p>${dl([['Driver',t.driver],['Lane',t.lane],['Voltage',t.voltage],['Direction',t.direction||'Unknown'],['Magnets',t.magnetStatus||'Unknown'],['Laps',t.laps],['Best (seconds)',t.best],['Average (seconds)',t.average]])}<p class="prewrap mt">${esc(t.notes)}</p>${local()?btn('View recorded configuration','test-snapshot','small',t.id):''}`)).join(''):empty('Keep track of your testing','Record the setup, conditions, figures and how the car felt.')}`;}
  if(section==='Photos & documents')return `<div class="page-head"><div><h2>Car photographs</h2><p class="muted">Photos are stored with your database and included in complete backups.</p></div>${local()?btn('Add photo','add-photo','primary',c.id):''}</div><div class="photo-grid">${c.picture?`<div class="panel">${photo(c)}<p>Main photograph</p>${local()?btn('Replace','main-photo','small',c.id):''}</div>`:''}${(c.photos||[]).map(p=>`<div class="panel"><img src="${esc(p.data)}" alt="${esc(p.name)}"><p>${esc(p.name)}</p>${local()?btn('Remove','delete-photo','small',p.id):''}</div>`).join('')}</div>${!c.picture&&!c.photos?.length?`<div class="compact-photo-empty">${empty('Add a photograph','Use a PNG, JPEG or WebP image of the car or its components.',local()?btn('Choose main photo','main-photo','primary',c.id):'')}</div>`:''}${renderDocuments(c)}`;
  return '';
}
function available(p){if(local()&&db._view?.available&&Object.hasOwn(db._view.available,p.id))return db._view.available[p.id];const reserved=(current().assemblies||[]).filter(a=>!a.dismantled&&!a.carId).flatMap(a=>a.components).filter(c=>c.partId===p.id).reduce((n,c)=>n+c.quantity,0);return p.quantity-reserved-current().installations.filter(i=>i.partId===p.id&&!i.removed).reduce((n,i)=>n+i.quantity,0);}
